css:
.d-table-row-validation{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-table-row-validation *,.d-table-row-validation *::before,.d-table-row-validation *::after{box-sizing:border-box}
.d-table-row-validation [hidden]{display:none!important}
.d-table-row-validation .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-table-row-validation .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-table-row-validation label{display:block;margin:8px 0}
.d-table-row-validation input,.d-table-row-validation select,.d-table-row-validation textarea,.d-table-row-validation button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-table-row-validation input:not([type=checkbox]):not([type=radio]),.d-table-row-validation select,.d-table-row-validation textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-table-row-validation button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-table-row-validation button:disabled{opacity:.5;cursor:default}
.d-table-row-validation :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-table-row-validation [aria-invalid=true]{border-color:var(--warn)!important}
.d-table-row-validation .d-scroll{max-width:100%;overflow:auto}
.d-table-row-validation table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-table-row-validation th,.d-table-row-validation td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-table-row-validation caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-table-row-validation progress{width:100%;accent-color:var(--ink)}
.d-table-row-validation pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-table-row-validation h3,.d-table-row-validation p{margin:8px 0}
.d-table-row-validation [aria-pressed=true],.d-table-row-validation [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-table-row-validation .d-grow{flex:1;min-width:100px}
.d-table-row-validation summary{cursor:pointer;padding:6px 0}
.d-table-row-validation ul,.d-table-row-validation ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-check]').onclick=()=>{const seen=new Set(),lines=q('[data-rows]').value.split(/\r?\n/).filter(line=>line.trim());let errors=0;q('[data-result]').replaceChildren(...lines.map((line,i)=>{const fields=line.split(',').map(s=>s.trim()),id=fields[0],duration=Number(fields[1]),reasons=[];if(fields.length!==2)reasons.push('需要两列');if(!id)reasons.push('缺少编号');if(seen.has(id))reasons.push('编号重复');seen.add(id);if(!fields[1]||!Number.isFinite(duration)||duration<1||duration>120)reasons.push('时长须为 1–120 秒');if(reasons.length)errors++;const li=document.createElement('li');li.textContent='第 '+(i+1)+' 行：'+(reasons.join('；')||'通过');return li;}));say(lines.length?'检查 '+lines.length+' 行，'+errors+' 行有问题':'没有可检查的记录');};})(root, q, qa, say);
}
